def lib(z, size):
    import itertools as it
    terms = [(f'{i}', u) for (i, u) in enumerate(z.T)]
    for deg in range(2, 4):
        terms.extend((('*'.join(map(str, ii)), np.prod(z[:, ii], axis=1)) for ii in it.combinations_with_replacement(range(4), deg)))
    if size == 0:
        return terms
    args = terms[:4].copy()
    for (i, j) in it.combinations(range(4), 2):
        (u, v) = (z[:, i], z[:, j])
        args.extend([(f'{i}+{j}', u + v), (f'{i}-{j}', u - v)])
        terms.extend([(f'{i}{j}/norm', u * v / (1 + u * u + v * v)), (f'{i}{j}/sum', u * v / (1 + (u + v) ** 2)), (f'{i}{j}/diff', u * v / (1 + (u - v) ** 2))])
        for k in (0.25, 0.5, 1, 2):
            for (a, b, p, r) in ((i, j, u, v), (j, i, v, u)):
                terms.append((f'{a}/(1+{k}*{b}^2)', p / (1 + k * r * r)))
    for (name, u) in args:
        for k in (0.5, 1, 1.5, 2, 3):
            for f in (np.tanh, np.sin, np.cos, np.arctan):
                terms.append((f'{f.__name__}({k}*{name})', f(k * u)))
        terms.extend([(f'sat{name}', u / (1 + abs(u))), (f'abs{name}', abs(u))])
    return terms

def _features(z):
    from itertools import combinations
    s = [np.ones(len(z)), z]
    for j in range(4):
        u = z[:, j:j + 1]
        s.extend([u ** 2, u ** 3, u ** 4, np.tanh(u), np.arctan(u), u / (1 + abs(u)), np.exp(-u * u / 2)])
    groups = []
    for (i, j) in combinations(range(4), 2):
        (u, v) = (z[:, i:i + 1], z[:, j:j + 1])
        g = [u * v, u * u * v, u * v * v, u * u * v * v, u ** 3 * v, u * v ** 3, u * v / (1 + 0.5 * (u * u + v * v))]
        for sign in (-1, 1):
            w = (u + sign * v) / 1.4
            g.extend([np.sin(w), np.cos(w), np.tanh(w), w / (1 + abs(w)), np.exp(-w * w / 2)])
        groups.append(np.column_stack(g))
    return (s, groups)
